import { splitProps, type JSX, type ParentProps } from 'solid-js';
import { emptyStyleKeys, getEmptyMediaVariantKey } from '../lib/core';
import type { EmptyMediaBaseProps } from '../lib/core';
import styles from './empty.module.scss';

function primitive(key: keyof typeof emptyStyleKeys, slot: string) {
	return (props: ParentProps<JSX.HTMLAttributes<HTMLDivElement>>) => {
		const [local, rest] = splitProps(props, ['class', 'children']);
		return (
			<div {...rest} data-slot={slot} class={`${styles[emptyStyleKeys[key]]} ${local.class ?? ''}`}>
				{local.children}
			</div>
		);
	};
}
export interface EmptyProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export const Empty = primitive('root', 'empty');
export interface EmptyHeaderProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export const EmptyHeader = primitive('header', 'empty-header');
export interface EmptyTitleProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export const EmptyTitle = primitive('title', 'empty-title');
export interface EmptyDescriptionProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export const EmptyDescription = primitive('description', 'empty-description');
export interface EmptyContentProps extends JSX.HTMLAttributes<HTMLDivElement> {}
export const EmptyContent = primitive('content', 'empty-content');
export interface EmptyMediaProps extends JSX.HTMLAttributes<HTMLDivElement>, EmptyMediaBaseProps {}
export function EmptyMedia(props: ParentProps<EmptyMediaProps>) {
	const [local, rest] = splitProps(props, ['class', 'children', 'variant']);
	const variant = () => local.variant ?? 'default';
	return (
		<div {...rest} data-slot="empty-icon" data-variant={variant()} class={`${styles[emptyStyleKeys.media]} ${styles[getEmptyMediaVariantKey(variant())]} ${local.class ?? ''}`}>
			{local.children}
		</div>
	);
}
export default Empty;

@use '../../../styles/variables/colors' as *;

// Empty 根容器
.root {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	gap: $spacing-6;
	border-radius: var(--tile-empty-radius, $radius);
	border: 1px var(--tile-empty-border-style, dashed) var(--tile-empty-border, $border);
	background-color: var(--tile-empty-background, transparent);
	padding: var(--tile-empty-padding, $spacing-6);
	text-align: center;
	text-wrap: balance;

	// 大屏加深内边距
	@media (min-width: 768px) {
		padding: var(--tile-empty-padding, $spacing-12);
	}
}

// 头部：媒体 + 标题 + 描述
.header {
	display: flex;
	max-width: 24rem;
	flex-direction: column;
	align-items: center;
	gap: var(--tile-empty-header-gap, $spacing-2);
	text-align: center;
}

// 媒体区（图标容器）
.media {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	margin-bottom: $spacing-2;

	svg {
		pointer-events: none;
		flex-shrink: 0;
	}

	// 变体
	&.variantDefault {
		background-color: transparent;
	}

	&.variantIcon {
		width: $spacing-10;
		height: $spacing-10;
		border-radius: $radius;
		background-color: var(--tile-empty-media-background, $muted);
		color: $foreground;

		svg {
			width: $spacing-6;
			height: $spacing-6;
		}
	}
}

// 标题
.title {
	font-size: var(--tile-empty-title-size, $text-lg);
	font-weight: var(--tile-empty-title-weight, $font-medium);
	letter-spacing: var(--tile-empty-title-tracking, -0.01em);
}

// 描述
.description {
	font-size: var(--tile-empty-description-size, $text-sm);
	line-height: var(--tile-empty-description-leading, $leading-relaxed);
	color: var(--tile-empty-description-color, $muted-foreground);

	a {
		text-decoration: underline;
		text-underline-offset: 4px;
	}

	a:hover {
		color: $primary;
	}
}

// 内容区（操作按钮等）
.content {
	display: flex;
	width: 100%;
	max-width: 24rem;
	min-width: 0;
	flex-direction: column;
	align-items: center;
	gap: $spacing-4;
	font-size: $text-sm;
	text-wrap: balance;
}
